using LiBot.Application.Interfaces; using LiBot.Application.Models.BookTransaction;
namespace LiBot.Application.Services;
public sealed class BookTransactionService(IBookTransactionRepository repository) : IBookTransactionService { public Task<TransactionListResponse> ListReceiptsAsync(int p,int s,string? t,string? st,string? q,DateOnly? f,DateOnly? to,CancellationToken c)=>repository.ListReceiptsAsync(p,s,t,st,q,f,to,c); public Task<TransactionResponse?> GetReceiptAsync(Guid id,CancellationToken c)=>repository.GetReceiptAsync(id,c); public Task<TransactionResponse>CreateReceiptAsync(CreateBookReceiptRequest r,CancellationToken c)=>repository.CreateReceiptAsync(r,c); public Task<TransactionResponse>UpdateReceiptAsync(Guid id,CreateBookReceiptRequest r,CancellationToken c)=>repository.UpdateReceiptAsync(id,r,c); public Task<TransactionResponse>UpdateReceiptStatusAsync(Guid id,string s,CancellationToken c)=>repository.UpdateReceiptStatusAsync(id,s,c); public Task<TransactionListResponse> ListIssuesAsync(int p,int s,string? t,string? st,string? q,DateOnly? f,DateOnly? to,CancellationToken c)=>repository.ListIssuesAsync(p,s,t,st,q,f,to,c); public Task<TransactionResponse?>GetIssueAsync(Guid id,CancellationToken c)=>repository.GetIssueAsync(id,c); public Task<TransactionResponse>CreateIssueAsync(CreateBookIssueRequest r,CancellationToken c)=>repository.CreateIssueAsync(r,c); public Task<TransactionResponse>UpdateIssueAsync(Guid id,CreateBookIssueRequest r,CancellationToken c)=>repository.UpdateIssueAsync(id,r,c); public Task<TransactionResponse>UpdateIssueStatusAsync(Guid id,string s,CancellationToken c)=>repository.UpdateIssueStatusAsync(id,s,c); }
